contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint futureTime) public payable {
        require(address(this).balance >= amount);
        require(futureTime > 0);

        // Move the contract's pastBlockTime forward so we can test a valid-timestamp call.
        c.fallback{value: 10 ether}();
        uint t0 = c.pastBlockTime();

        uint cBalBefore = address(c).balance;
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint t1 = c.pastBlockTime();
        uint cBalAfter = address(c).balance;

        if (reverted) {
            // A revert restores old state: pastBlockTime and c.balance are unchanged.
            assert(t1 == t0 && cBalAfter == cBalBefore);
        } else {
            // A non-revert requires exactly 10 ether and an advancing timestamp.
            // pastBlockTime is updated to block.timestamp + 1, which is strictly greater than t0.
            assert(amount == 10 ether && t1 > t0);
        }
    }

    receive() external payable {}

    fallback() external payable {}
}

