contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint dt) public payable {
        require(address(this).balance >= amount);

        uint before = c.pastBlockTime();

        bool reverted;
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterValue = c.pastBlockTime();

        if (amount != 10 ether) {
            assert(reverted && afterValue == before);
