contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amountToSend, uint timestampOffset) public payable {
        // Ensure enough balance to attempt a fixed 10 ether call.
        require(address(this).balance >= amountToSend);

        // Read the contract's observable timestamp state before any mutation.
        uint pastBefore = c.pastBlockTime();

        // Try the fallback with the required amount. Capture whether it reverted.
        bool reverted;
        try c.fallback{value: amountToSend}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable post-state.
        uint pastAfter = c.pastBlockTime();
        uint contractBalance = address(c).balance;

        // The general rule:
        // 1. Any call sending exactly 10 ether either reverts and leaves pastBlockTime unchanged,
        //    or succeeds, advances pastBlockTime to block.timestamp + 1 (strictly greater than before),
        //    and either pays out the whole balance (when block.number % 15 == 0) or retains it.
        // 2. Any call sending a different amount must revert and leave pastBlockTime unchanged.
        assert(
            (amountToSend != 10 ether && reverted && pastAfter == pastBefore) ||
            (amountToSend == 10 ether && 
                (
                    (reverted && pastAfter == pastBefore) ||
                    (!reverted && pastAfter > pastBefore && pastAfter == block.timestamp + 1 &&
                        ((block.number % 15 == 0 && contractBalance == 0) ||
                         (block.number % 15 != 0 && contractBalance == amountToSend)))
                )
            )
        );
    }

    receive() external payable {}
}

