contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint firstValue, uint firstNumber) public payable {
        require(address(this).balance >= 20 ether, "need enough balance");
        require(firstValue >= 10 ether, "need at least 10 ether");
        require(firstNumber > 0, "block number must be positive");

        // Fund the contract so we can attempt the first fallback call.
        // The parameter controls how much we send during the first call.

        bool firstReverted;
        uint firstPastBlockTimeBefore;
        uint firstCallerBalanceBefore;
        uint firstPastBlockTimeAfterFirst;
        uint firstCallerBalanceAfterFirst;
        uint cBalanceAfterFirst;

        firstPastBlockTimeBefore = c.pastBlockTime();
        firstCallerBalanceBefore = address(this).balance;

        uint firstSend = firstValue < address(this).balance ? firstValue : address(this).balance;
        if (firstSend >= 10 ether) {
            try c.fallback{value: firstSend}() {
                firstReverted = false;
            } catch {
                firstReverted = true;
            }
        } else {
            firstReverted = true;
        }

        firstPastBlockTimeAfterFirst = c.pastBlockTime();
        firstCallerBalanceAfterFirst = address(this).balance;
        cBalanceAfterFirst = address(c).balance;

        bool pastBlockTimeUpdated = !firstReverted && firstPastBlockTimeAfterFirst > firstPastBlockTimeBefore;
        bool callerPaidWithPayout = !firstReverted && firstCallerBalanceAfterFirst > firstCallerBalanceBefore;
        bool exactlyTenEtherSent = !firstReverted && (firstCallerBalanceBefore - firstCallerBalanceAfterFirst) == 10 ether;
        bool balanceMovedToC = !firstReverted && cBalanceAfterFirst == 10 ether;

        bool secondReverted;
        uint cBalanceBeforeSecond = address(c).balance;
        uint callerBalanceBeforeSecond = address(this).balance;

        // A second call tries to use the same timestamp; since pastBlockTime was advanced by one,
        // it may still succeed if the next timestamp is high enough, but the balance only changes
        // by the exact value sent: either the full payout on a modulo-15 block, or exactly 10 ether.
        // We use a value that is at least 10 ether to keep the precondition satisfiable.
        uint secondSend = address(this).balance >= 10 ether ? 10 ether : 0;
        if (!firstReverted && secondSend == 10 ether) {
            try c.fallback{value: secondSend}() {
                secondReverted = false;
            } catch {
                secondReverted = true;
            }
        } else {
            secondReverted = true;
        }

        uint cBalanceAfterSecond = address(c).balance;
        uint callerBalanceAfterSecond = address(this).balance;

        bool onlyTenEtherMovedOnSecond = secondReverted || cBalanceAfterSecond >= cBalanceBeforeSecond;
        bool callerDidNotLoseMoreThanTen = secondReverted || callerBalanceBeforeSecond - callerBalanceAfterSecond <= 10 ether;

        assert(
            pastBlockTimeUpdated
            && exactlyTenEtherSent
            && balanceMovedToC
            && callerDidNotLoseMoreThanTen
            && onlyTenEtherMovedOnSecond
        );
    }

    fallback() external payable {}
    receive() external payable {}
}

