        c.fallback{value: amount}();

        // Read the timestamp barrier after the successful call.
        uint afterSetup = c.pastBlockTime();

        // Only a call made after that timestamp can succeed.
        require(block.timestamp >= afterSetup);

        // Wait-time parameter is not needed for the rule; it is kept as an input to vary execution.
        require(waitTime >= 0);

