        // triggered the payout branch, in which case the whole balance is sent to the caller.
        assert(
            reverted
                ? newPastBlockTime == afterSetup
                : (
                    newPastBlockTime == block.timestamp + 1
                    && (
                        (block.number % 15 == 0 && balanceAfter == 0)
                        || (block.number % 15 != 0 && balanceAfter == balanceBefore + amount)
                    )
                )
        );
    }

    receive() external payable {}

