contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint waitBlocks) public payable {
        require(address(this).balance >= amount);
        require(amount == 10 ether);

        // Record the previous successful timestamp.
        uint prev = c.pastBlockTime();
        uint balBefore = address(c).balance;

        // Advance the EVM time so timestamp is strictly greater than prev,
        // then call the fallback.  Because the fallback can only succeed when
        // block.timestamp > prev, we must make time move forward.
        // (No cheatcodes allowed, but block.timestamp in a test is already the
        //  time of the test transaction; if prev is 0 the first call always
        //  succeeds, otherwise we rely on the fact that the test itself runs at
        //  a later timestamp than any setup call.)
        bool reverted;
        try c.{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the call is either rejected because the timestamp has
        // not advanced, or it succeeds and then pastBlockTime equals the new
        // timestamp + 1.  When the block number is divisible by 15 the entire
        // contract balance must have been transferred to the caller.
        // We express this as: if the call did not revert, pastBlockTime must be
        // strictly greater than the previous pastBlockTime, and the balance
        // change is either the full old balance (payout) or zero (no payout),
        // and a payout occurs exactly when block.number % 15 == 0.
        uint newTime = c.pastBlockTime();
        uint balAfter = address(c).balance;
        bool payout = (balAfter < balBefore);

        assert(
            reverted ||
            (
                newTime > prev &&
                (
                    (block.number % 15 == 0 && payout && balAfter == 0) ||
                    (block.number % 15 != 0 && !payout && balAfter == balBefore)
                )
            )
        );
    }

    receive() external payable {}
}

